"""Fresh28-entry release, previous venture normal budget, island full supply restore/native wins."""
import argparse,asyncio,datetime,json
from playwright.async_api import async_playwright
from test_island_browser import ROOT,FIELDS,snap,plans,execute,load,watch,click
import test_venture_browser as venture
async def main(args):
 out=ROOT/args.out;out.parent.mkdir(parents=True,exist_ok=True);allplans=await plans();oldplans=await venture.plans();errors=[];bad=[];failed=[];report={'testedAt':datetime.datetime.now(datetime.timezone.utc).isoformat(),'url':args.url,'entryPages':[]}
 def save():report.update(consoleErrors=errors,badResponses=bad,requestFailures=failed);out.write_text(json.dumps(report,ensure_ascii=False,indent=2)+'\n',encoding='utf8')
 async with async_playwright() as pw:
  b=await pw.chromium.launch()
  try:
   ctx=await b.new_context(viewport={'width':1360,'height':1200});p=await ctx.new_page();watch(p,errors,bad,failed);base=args.url.rstrip('/')+'/'
   await p.goto(base);await p.locator('.lab-card').last.wait_for();await p.wait_for_load_state('networkidle');data=await p.evaluate('async()=>await(await fetch("./data/games.json")).json()');assert len(data['games'])==72 and len(data['groups'])==10 and len(data['experiments'])==28 and sum(e['levels'] for e in data['experiments'])==346 and data['version']=='2026.10.16.28';assert await p.locator('.lab-card .primary-link').count()==28;report['atlas']={'entries':72,'groups':10,'originals':28,'levels':346,'version':data['version']};save()
   for e in data['experiments']:
    r=await p.goto(base+e['url'].removeprefix('./'));await p.wait_for_load_state('networkidle');assert r.status==200 and await p.locator('h1').count()==1 and await p.locator('main').count()>=1 and await p.locator('script[type=module]').count()>=1,e['id'];report['entryPages'].append({'id':e['id'],'status':r.status,'title':await p.title()});save()
   await venture.load(p,base+'games/venture/');await p.locator('#help-confirm').click();old=await venture.execute(p,oldplans[0]['commands']);assert old['state']=='won' and old['cash']==40 and old['worth']==56;report['previousGame']={'id':'venture','state':old['state'],'cash':old['cash'],'worth':old['worth'],'stats':old['stats'],'actualLog':old['log']};save()
   await load(p,base+'games/island/');await p.locator('#help-confirm').click();commands=allplans[0]['commands'];prefix=next(i+1 for i,c in enumerate(commands) if c['kind']=='end');await execute(p,commands[:prefix]);await p.keyboard.press('p');before=await snap(p);await load(p,base+'games/island/',True);after=await snap(p);assert after['state']=='paused' and after['ui']['pending'] is None and all(before[k]==after[k] for k in FIELDS);await p.wait_for_timeout(500);waited=await snap(p);assert all(waited[k]==after[k] for k in FIELDS);await p.locator('#resume').click();end=await execute(p,commands[prefix:]);assert end['state']=='won' and end['cash']==allplans[0]['cash'] and end['stock']==allplans[0]['stock'];report['restoreAndWin']={'state':end['state'],'cash':end['cash'],'stock':end['stock'],'turn':end['turn'],'exactFields':FIELDS,'restoredRevision':after['revision'],'stats':end['stats'],'actualLog':end['log']};save();await ctx.close()
   ctx=await b.new_context(viewport={'width':390,'height':844},is_mobile=True,has_touch=True);p=await ctx.new_page();watch(p,errors,bad,failed);await load(p,base+'games/island/');await click(p,'#help-confirm',True);end=await execute(p,commands,touch=True);assert end['state']=='won' and end['cash']==allplans[0]['cash'] and end['stock']==allplans[0]['stock'];report['nativeTouch']={'state':end['state'],'cash':end['cash'],'stock':end['stock'],'turn':end['turn'],'stats':end['stats'],'actualLog':end['log'],'method':'Native tutorial/tool/grid/rotation/cost receipt/round confirmation taps; map positioning helper only.'};await ctx.close();assert not errors and not bad and not failed,(errors,bad,failed);report['passed']=True;save();print(json.dumps({'passed':True,'entryPages':len(report['entryPages']),'previousCash':report['previousGame']['cash'],'restoreCash':report['restoreAndWin']['cash'],'nativeCash':report['nativeTouch']['cash']}))
  except Exception as e:report['error']=str(e)[:1800];raise
  finally:save();await b.close()
if __name__=='__main__':
 a=argparse.ArgumentParser();a.add_argument('--url',default='https://yydshly.github.io/classic-games-atlas/');a.add_argument('--out',default='.local/island-final-smoke.json');asyncio.run(main(a.parse_args()))
